# Creates Owner B's web files in the CURRENT folder (run from the project root).
if (-not (Test-Path 'shared')) { Write-Host 'WARNING: no shared folder here - are you in the project root?' -ForegroundColor Yellow }
$files = [ordered]@{
  'web\index.html' = ''
  'web\src\config_loader.js' = ''
  'web\src\map_aoi.js' = ''
  'web\src\aggregate.js' = ''
  'web\src\alarm_logic.js' = ''
  'web\src\calendar_view.js' = ''
  'web\src\report_view.js' = ''
  'web\src\main.js' = ''
}
foreach ($k in $files.Keys) {
  $full = Join-Path (Get-Location).Path $k
  New-Item -ItemType Directory -Force (Split-Path $full) | Out-Null
  [System.IO.File]::WriteAllBytes($full, [Convert]::FromBase64String($files[$k]))
  Write-Host ('created ' + $k + '  (' + (Get-Item $full).Length + ' bytes)')
}
